84	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
85	    @Override
86	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
87	        Collection<Owner> owners;
88	        if (lastName != null) {
89	            owners = this.clinicService.findOwnerByLastName(lastName);
90	        } else {
91	            owners = this.clinicService.findAllOwners();
92	        }
93	        if (owners.isEmpty()) {
94	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
95	        }
96	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
97	    }
98	
99	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
100	    @Override
101	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
102	        Owner owner = this.clinicService.findOwnerById(ownerId);
103	        if (owner == null) {
104	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
105	        }
106	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
107	    }
108	
109	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
110	    @Override
111	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
112	        // Normalize the address up front so every downstream use (the required-field check,
113	        // household-duplicate detection, the shared household id and the stored/returned value)
114	        // works from the same canonical form.
115	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
116	        List<String> missingFields = new ArrayList<>();
117	        if (isBlank(ownerFieldsDto.getFirstName())) {
118	            missingFields.add("firstName");
119	        }
120	        if (isBlank(ownerFieldsDto.getLastName())) {
121	            missingFields.add("lastName");
122	        }
123	        // Reject an address that is blank once normalized (e.g. whitespace-only input).
124	        if (isBlank(normalizedAddress)) {
125	            missingFields.add("address");
126	        }
127	        if (isBlank(ownerFieldsDto.getCity())) {
128	            missingFields.add("city");
129	        }
130	        if (isBlank(ownerFieldsDto.getTelephone())) {
131	            missingFields.add("telephone");
132	        }
133	        if (!missingFields.isEmpty()) {
134	            throw new InvalidOwnerFieldsException(missingFields);
135	        }
136	        // Normalize the telephone into E.164 form; a number that cannot form a valid
137	        // E.164 value is rejected with a 400.
138	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
139	        // Email is optional; when present it must be a syntactically valid address and is
140	        // stored lower-cased. An invalid address is rejected with a 400.
141	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
142	        // Reject the request if the E.164 telephone is already used by any other owner.
143	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
144	            .map(Owner::getTelephone)
145	            .filter(existing -> existing != null)
146	            .anyMatch(normalizedTelephone::equals);
147	        if (telephoneInUse) {
148	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
149	        }
150	        // Household handling for a matching last name + address (compared case-insensitively with
151	        // collapsed whitespace). By default such a request is rejected as a duplicate household;
152	        // when the caller opts in via 'sharesHousehold' the owner is instead admitted into the shared
153	        // household and every member (the new owner and any existing ones) is stamped with the same
154	        // stable 'householdId'.
155	        String normalizedLastName = collapse(ownerFieldsDto.getLastName());
156	        String householdId = null;
157	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
158	            householdId = householdId(normalizedLastName, normalizedAddress);
159	            // Backfill the shared identifier onto any existing member of this household so the whole
160	            // household carries the same stable value.
161	            for (Owner existing : this.clinicService.findAllOwners()) {
162	                if (collapse(existing.getLastName()).equals(normalizedLastName)
163	                    && normalizeAddress(existing.getAddress()).equals(normalizedAddress)
164	                    && !householdId.equals(existing.getHouseholdId())) {
165	                    existing.setHouseholdId(householdId);
166	                    this.clinicService.saveOwner(existing);
167	                }
168	            }
169	        } else {
170	            boolean householdInUse = this.clinicService.findAllOwners().stream()
171	                .anyMatch(existing -> collapse(existing.getLastName()).equals(normalizedLastName)
172	                    && normalizeAddress(existing.getAddress()).equals(normalizedAddress));
173	            if (householdInUse) {
174	                throw new DuplicateOwnerHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
175	            }
176	        }
177	        HttpHeaders headers = new HttpHeaders();
178	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
179	        owner.setAddress(normalizedAddress);
180	        owner.setTelephone(normalizedTelephone);
181	        owner.setEmail(normalizedEmail);
182	        owner.setHouseholdId(householdId);
183	        // Record how many existing owners (before this create) share this owner's first and last
184	        // name, compared case-insensitively. Computed against the current owners so the new owner
185	        // itself is never counted.
186	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
187	        // When no registration date is supplied, default it to the server's current date.
188	        if (owner.getRegistrationDate() == null) {
189	            owner.setRegistrationDate(LocalDate.now());
190	        }
191	        // Assign the customer code: '<CITY3>-<LAST3>-<NNNN>' where CITY3 is the upper-cased first
192	        // three letters of the city, LAST3 the upper-cased first three letters of the last name and
193	        // NNNN is a per-city 4-digit zero-padded sequence equal to one more than the number of
194	        // owners already in that city.
195	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
196	        this.clinicService.saveOwner(owner);
197	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
198	        headers.setLocation(UriComponentsBuilder.newInstance()
199	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
200	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
201	    }
